"""Shared workflow exception hierarchy.

Broken import cycle: work_items imports this at top level; this imports
ReasonRequiredError from work_items (same class object) so legacy + workflow
gates share one reason exception. No dependency on workflow_crud/workflow_moves.
"""
from __future__ import annotations

from mem_mcp.mindmap.work_items import ReasonRequiredError  # reused gate


class WorkflowError(Exception):
    """Base for all workflow domain errors."""


class MoveBlockedError(WorkflowError):
    def __init__(self, current_stage: str, requested_stage: str, reason: str) -> None:
        super().__init__(f"move blocked from {current_stage} to {requested_stage}: {reason}")
        self.current_stage = current_stage
        self.requested_stage = requested_stage
        self.reason = reason


class SignoffRequiredError(WorkflowError):
    def __init__(self, current_stage: str, requested_stage: str) -> None:
        super().__init__(f"sign-off required from {current_stage} to {requested_stage}")
        self.current_stage = current_stage
        self.requested_stage = requested_stage


class SignoffCompleteError(WorkflowError):
    def __init__(self, request_id: str) -> None:
        super().__init__(f"sign-off complete for request {request_id}")
        self.request_id = request_id


class WorkflowNotFoundError(WorkflowError):
    def __init__(self, workflow_id: str | None = None) -> None:
        msg = f"workflow not found: {workflow_id}" if workflow_id else "workflow not found"
        super().__init__(msg)
        self.workflow_id = workflow_id


class WorkflowPermissionDeniedError(WorkflowError):
    def __init__(self, permission: str, team_id: str) -> None:
        super().__init__(f"permission denied: {permission} for team {team_id}")
        self.permission = permission
        self.team_id = team_id


class StageNotFoundError(WorkflowError):
    def __init__(self, stage: str) -> None:
        super().__init__(f"stage not found: {stage}")
        self.stage = stage


class TransitionNotFoundError(WorkflowError):
    def __init__(self, from_stage: str, to_stage: str) -> None:
        super().__init__(f"transition not found: {from_stage} -> {to_stage}")
        self.from_stage = from_stage
        self.to_stage = to_stage


class StageConflictError(WorkflowError):
    def __init__(self, expected: str, actual: str) -> None:
        super().__init__(f"stage conflict: expected {expected}, actual {actual}")
        self.expected = expected
        self.actual = actual


class SignoffAlreadySignedError(WorkflowError):
    def __init__(self, signatory_tenant_id: str) -> None:
        super().__init__(f"already signed by {signatory_tenant_id}")
        self.signatory_tenant_id = signatory_tenant_id


class SignoffNotAllowedError(WorkflowError):
    def __init__(self, signatory_tenant_id: str) -> None:
        super().__init__(f"sign-off not allowed for {signatory_tenant_id}")
        self.signatory_tenant_id = signatory_tenant_id


class WorkflowNotActiveError(WorkflowError):
    def __init__(self, workflow_id: str | None = None) -> None:
        msg = f"workflow not active: {workflow_id}" if workflow_id else "workflow not active"
        super().__init__(msg)
        self.workflow_id = workflow_id


class WorkflowAlreadyActiveError(WorkflowError):
    def __init__(self, workflow_id: str | None = None) -> None:
        msg = f"workflow already active: {workflow_id}" if workflow_id else "workflow already active"
        super().__init__(msg)
        self.workflow_id = workflow_id


class KindNotAllowedError(WorkflowError):
    def __init__(self, kind: str, allowed: tuple[str, ...]) -> None:
        super().__init__(f"kind not allowed: {kind}; allowed: {allowed}")
        self.kind = kind
        self.allowed = allowed
EOF
